const EnvelopeLoadRetainBuilder = "Envelope: retention requires a region round trip through the VARIABLE form"
const EnvelopeSaveRetainMessages = "Envelope: retention requires a region round trip through the VARIABLE form"

func EnvelopeLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Envelope {
	return (*Envelope)(tableRegionLoadRetain(region, wire, EnvelopeTableType(), EnvelopeTableType().NodeType, 2, report, retain))
}
func EnvelopeMeasureRetain(value *Envelope, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), EnvelopeTableType(), nil, true, retain, nil, allocator...)
}
func EnvelopeSaveRetain(value *Envelope, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), EnvelopeTableType(), buffer, false, retain, report, allocator...)
}
func EnvelopeMeasureBodyRetain(value *Envelope, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !EnvelopeSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func EnvelopeSaveBodyRetain(w *TableRetainWriter, value *Envelope) bool {
	if !EnvelopeSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
