func EnvelopeLoadBuilder(b *EnvelopeBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, EnvelopeTableType(), EnvelopeTableType().NodeType, 2, report)
}

// EnvelopeReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func EnvelopeReadStrict(wire []byte) (*Envelope, error) {
	var b EnvelopeBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := EnvelopeLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type EnvelopeBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *EnvelopeBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Envelope{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	EnvelopeReset((*Envelope)(p))
	return true
}
func (b *EnvelopeBuilder) GetRoot() *Envelope {
	if b.Arena.Locked {
		return nil
	}
	return (*Envelope)(b.Arena.At(b.root))
}
func (b *EnvelopeBuilder) AsConst() *Envelope {
	if len(b.region) == 0 {
		return nil
	}
	return (*Envelope)(unsafe.Pointer(&b.region[0]))
}
func (b *EnvelopeBuilder) Region() []byte { return b.region }
func (b *EnvelopeBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), EnvelopeTableType(), &b.Arena)
}
